107	    public void initialize() {
108	        try (Connection conn = getConnection()) {
109	            createTables(conn);
110	            loadInitialCatalog(conn);
111	        } catch (SQLException e) {
112	            throw new RuntimeException("Failed to initialize database", e);
113	        }
