277	    public CheckoutSummary calculateSummary(CheckoutRequest request, Connection conn) throws SQLException {
278	        validateRequest(request, conn);
279	
280	        Set<String> skus = new HashSet<>();
281	        for (OrderItem item : request.getItems()) {
282	            skus.add(item.getSku());
283	        }
284	        Map<String, Product> products = productRepository.findBySkus(skus);
285	
286	        BigDecimal productsSubtotal = calculateProductsSubtotal(request.getItems(), products);
287	
288	        BigDecimal totalWeight = calculateTotalWeight(request.getItems(), products);
289	
290	        ShippingService.ShippingQuote shipping = shippingService.calculateShipping(
291	                request.getShippingMethod(), request.getZipCode(), totalWeight, request.getRegion());
292	
293	        BigDecimal shippingCost = shipping.cost;
294	        int deliveryDays = shipping.deliveryDays;
295	
296	        if (clubService.hasFreeShipping(request.getClubTier())
297	                && request.getShippingMethod() != ShippingMethod.COURIER) {
298	            shippingCost = BigDecimal.ZERO;
299	        }
300	
301	        boolean isFirstPurchase = false;
302	        if (conn != null) {
303	            long paidOrders = orderRepository.countPaidOrdersByCpf(conn, request.getCustomer().getCpf());
304	            isFirstPurchase = paidOrders == 0;
305	        }
306	
307	        BigDecimal couponDiscount = BigDecimal.ZERO;
308	        if (request.getCoupon() != null) {
309	            BigDecimal discount = couponService.calculateDiscount(
310	                    request.getCoupon(), productsSubtotal, shippingCost, request.getItems(),
311	                    products, request.getShippingMethod(), isFirstPurchase);
312	
313	            if (discount == null) {
314	                throw new BusinessException("COUPON_NOT_APPLICABLE", 422);
315	            }
316	
317	            couponDiscount = discount;
318	        }
319	
320	        BigDecimal insurance = calculateInsurance(productsSubtotal, request.getRegion());
321	
322	        BigDecimal orderTotal = productsSubtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
323	
324	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
325	
326	        PaymentService.PaymentCalculation payment = paymentService.calculatePayment(
327	                request.getPaymentMethod(), orderTotal, installments,
328	                request.getCoupon(), couponDiscount);
329	
330	        BigDecimal nextPurchaseCredit = clubService.calculateCredit(request.getClubTier(), productsSubtotal);
331	        boolean gift = clubService.hasGift(request.getClubTier(), productsSubtotal);
332	
333	        CheckoutSummary summary = new CheckoutSummary();
334	        summary.setProductsSubtotal(productsSubtotal);
335	        summary.setCouponDiscount(couponDiscount);
336	        summary.setShippingCost(shippingCost);
337	        summary.setDeliveryDays(deliveryDays);
338	        summary.setInsurance(insurance);
339	        summary.setPaymentAdjustment(payment.adjustment);
340	        summary.setFinalTotal(payment.finalTotal);
341	        summary.setInstallments(payment.installments);
342	        summary.setInstallmentAmount(payment.installmentAmount);
343	        summary.setNextPurchaseCredit(nextPurchaseCredit);
344	        summary.setGift(gift);
345	
346	        return summary;
347	    }
