349	    private void validateRequest(CheckoutRequest request, Connection conn) throws SQLException {
350	        if (request.getCustomer() == null || request.getCustomer().getCpf() == null
351	                || request.getCustomer().getEmail() == null) {
352	            throw new BusinessException("INVALID_ORDER", 422);
353	        }
354	
355	        if (request.getItems() == null || request.getItems().isEmpty()) {
356	            throw new BusinessException("INVALID_ORDER", 422);
357	        }
358	
359	        Set<String> seenSkus = new HashSet<>();
360	        for (OrderItem item : request.getItems()) {
361	            if (item.getSku() == null || item.getQuantity() <= 0) {
362	                throw new BusinessException("INVALID_ORDER", 422);
363	            }
364	            if (seenSkus.contains(item.getSku())) {
365	                throw new BusinessException("INVALID_ORDER", 422);
366	            }
367	            seenSkus.add(item.getSku());
368	        }
369	
370	        Map<String, Product> products = productRepository.findBySkus(seenSkus);
371	        for (OrderItem item : request.getItems()) {
372	            Product product = products.get(item.getSku());
373	            if (product == null) {
374	                throw new BusinessException("UNKNOWN_PRODUCT", 422);
375	            }
376	            if (product.isDiscontinued()) {
377	                throw new BusinessException("PRODUCT_DISCONTINUED", 422);
378	            }
379	            if (product.getStock() < item.getQuantity()) {
380	                throw new BusinessException("INSUFFICIENT_STOCK", 422);
381	            }
382	        }
383	
384	        if (request.getClubTier() == null) {
385	            throw new BusinessException("INVALID_CLUB_TIER", 422);
386	        }
387	
388	        if (request.getRegion() == null) {
389	            throw new BusinessException("INVALID_REGION", 422);
390	        }
391	
392	        if (request.getZipCode() == null || !request.getZipCode().matches("\\d{8}")) {
393	            throw new BusinessException("INVALID_ZIP_CODE", 422);
394	        }
395	
396	        if (request.getShippingMethod() == null) {
397	            throw new BusinessException("INVALID_SHIPPING_METHOD", 422);
398	        }
399	
400	        BigDecimal totalWeight = calculateTotalWeight(request.getItems(), products);
401	        if (request.getShippingMethod() == ShippingMethod.COURIER
402	                && totalWeight.compareTo(new BigDecimal("5.0")) > 0) {
403	            throw new BusinessException("SHIPPING_METHOD_UNAVAILABLE", 422);
404	        }
405	
406	        if (request.getCoupon() != null) {
407	        }
408	
409	        if (request.getPaymentMethod() == null) {
410	            throw new BusinessException("INVALID_PAYMENT_METHOD", 422);
411	        }
412	
413	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
414	        switch (request.getPaymentMethod()) {
415	            case PIX, BANK_SLIP -> {
416	                if (installments != 1) {
417	                    throw new BusinessException("INVALID_INSTALLMENTS", 422);
418	                }
419	            }
420	            case CREDIT_CARD -> {
421	                if (installments < 1 || installments > 12) {
422	                    throw new BusinessException("INVALID_INSTALLMENTS", 422);
423	                }
424	            }
425	        }
426	
427	        if (request.getPaymentMethod() == PaymentMethod.BANK_SLIP) {
428	            BigDecimal productsSubtotal = calculateProductsSubtotal(request.getItems(), products);
429	            ShippingService.ShippingQuote shipping = shippingService.calculateShipping(
430	                    request.getShippingMethod(), request.getZipCode(), totalWeight, request.getRegion());
431	            BigDecimal shippingCost = shipping.cost;
432	            if (clubService.hasFreeShipping(request.getClubTier())
433	                    && request.getShippingMethod() != ShippingMethod.COURIER) {
434	                shippingCost = BigDecimal.ZERO;
435	            }
436	
437	            boolean isFirstPurchase = false;
438	            if (conn != null) {
439	                long paidOrders = orderRepository.countPaidOrdersByCpf(conn, request.getCustomer().getCpf());
440	                isFirstPurchase = paidOrders == 0;
441	            }
442	
443	            BigDecimal couponDiscount = BigDecimal.ZERO;
444	            if (request.getCoupon() != null) {
445	                BigDecimal discount = couponService.calculateDiscount(
446	                        request.getCoupon(), productsSubtotal, shippingCost, request.getItems(),
447	                        products, request.getShippingMethod(), isFirstPurchase);
448	
449	                if (discount != null) {
450	                    couponDiscount = discount;
451	                }
452	            }
453	
454	            BigDecimal insurance = calculateInsurance(productsSubtotal, request.getRegion());
455	            BigDecimal orderTotal = productsSubtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
456	
457	            if (orderTotal.compareTo(new BigDecimal("1000.00")) > 0) {
458	                throw new BusinessException("PAYMENT_METHOD_UNAVAILABLE", 422);
459	            }
460	        }
461	    }
462	
463	    private BigDecimal calculateProductsSubtotal(List<OrderItem> items, Map<String, Product> products) {
464	        BigDecimal subtotal = BigDecimal.ZERO;
465	        for (OrderItem item : items) {
466	            Product product = products.get(item.getSku());
467	            BigDecimal itemTotal = product.getPrice()
468	                    .multiply(new BigDecimal(item.getQuantity()))
469	                    .setScale(2, RoundingMode.HALF_EVEN);
470	            subtotal = subtotal.add(itemTotal);
471	        }
472	        return subtotal;
473	    }
474	
475	    private BigDecimal calculateTotalWeight(List<OrderItem> items, Map<String, Product> products) {
476	        BigDecimal weight = BigDecimal.ZERO;
477	        for (OrderItem item : items) {
478	            Product product = products.get(item.getSku());
479	            BigDecimal itemWeight = product.getWeightKg()
480	                    .multiply(new BigDecimal(item.getQuantity()));
481	            weight = weight.add(itemWeight);
482	        }
483	        return weight;
484	    }
485	
486	    private BigDecimal calculateInsurance(BigDecimal productsSubtotal, Region region) {
487	        BigDecimal percentage = switch (region) {
488	            case SOUTHEAST, SOUTH -> new BigDecimal("0.01");
489	            case MIDWEST -> new BigDecimal("0.015");
490	            case NORTH -> new BigDecimal("0.025");
491	            case NORTHEAST -> new BigDecimal("0.02");
492	        };
493	
494	        BigDecimal insurance = productsSubtotal.multiply(percentage)
495	                .setScale(2, RoundingMode.HALF_EVEN);
496	
497	        BigDecimal limit = switch (region) {
498	            case NORTH, NORTHEAST -> new BigDecimal("30.00");
499	            case SOUTHEAST, SOUTH, MIDWEST -> null;
500	        };
501	
502	        if (limit != null && insurance.compareTo(limit) > 0) {
503	            return limit;
504	        }
505	
506	        return insurance;
507	    }
508	}
