518	    public BigDecimal calculateCredit(ClubTier tier, BigDecimal productsSubtotal) {
519	        BigDecimal percentage = switch (tier) {
520	            case BRONZE -> BigDecimal.ZERO;
521	            case SILVER -> new BigDecimal("0.02");
522	            case GOLD -> new BigDecimal("0.05");
523	        };
524	
525	        return productsSubtotal.multiply(percentage)
526	                .setScale(2, RoundingMode.HALF_EVEN);
527	    }
