529	    public boolean hasGift(ClubTier tier, BigDecimal productsSubtotal) {
530	        return tier == ClubTier.GOLD && productsSubtotal.compareTo(new BigDecimal("500.00")) > 0;
531	    }
532	
533	    public boolean hasFreeShipping(ClubTier tier) {
534	        return tier == ClubTier.GOLD;
535	    }
