537	package com.shop.service;
538	
539	import com.shop.model.OrderItem;
540	import com.shop.model.Product;
541	import com.shop.model.enums.CouponCode;
542	import com.shop.model.enums.ShippingMethod;
543	
544	import java.math.BigDecimal;
545	import java.math.RoundingMode;
546	import java.util.List;
547	import java.util.Map;
548	
549	public class CouponService {
550	
551	    public BigDecimal calculateDiscount(CouponCode coupon, BigDecimal productsSubtotal,
552	                                       BigDecimal shippingCost, List<OrderItem> items,
553	                                       Map<String, Product> products, ShippingMethod shippingMethod,
554	                                       boolean isFirstPurchase) {
555	        BigDecimal discount = switch (coupon) {
556	            case WELCOME10 -> {
557	                if (!isFirstPurchase) {
558	                    yield null;
559	                }
560	                yield productsSubtotal.multiply(new BigDecimal("0.10"))
561	                        .setScale(2, RoundingMode.HALF_EVEN);
562	            }
563	            case MINUS50 -> {
564	                if (productsSubtotal.compareTo(new BigDecimal("300.00")) < 0) {
565	                    yield null;
566	                }
567	                yield new BigDecimal("50.00");
568	            }
569	            case FREESHIPPING -> {
570	                if (shippingMethod == ShippingMethod.STORE_PICKUP) {
571	                    yield null;
572	                }
573	                yield shippingCost;
574	            }
575	            case BUY3PAY2 -> calculateBuy3Pay2Discount(items, products);
576	        };
577	
578	        if (discount == null) {
579	            return null;
580	        }
581	
582	        BigDecimal maxDiscount = productsSubtotal.multiply(new BigDecimal("0.30"))
583	                .setScale(2, RoundingMode.HALF_EVEN);
584	
585	        if (discount.compareTo(maxDiscount) > 0) {
586	            return maxDiscount;
587	        }
588	
589	        return discount;
590	    }
591	
592	    private BigDecimal calculateBuy3Pay2Discount(List<OrderItem> items, Map<String, Product> products) {
593	        BigDecimal discount = BigDecimal.ZERO;
594	
595	        for (OrderItem item : items) {
596	            if (item.getQuantity() >= 3) {
597	                int freeUnits = item.getQuantity() / 3;
598	                Product product = products.get(item.getSku());
599	                BigDecimal itemDiscount = product.getPrice()
600	                        .multiply(new BigDecimal(freeUnits))
601	                        .setScale(2, RoundingMode.HALF_EVEN);
602	                discount = discount.add(itemDiscount);
603	            }
604	        }
605	
606	        return discount;
607	    }
608	}
