55	    private PaymentCalculation calculateCreditCard(BigDecimal orderTotal, int installments) {
56	        if (installments <= 3) {
57	            BigDecimal installmentAmount = orderTotal.divide(new BigDecimal(installments), 2, RoundingMode.HALF_EVEN);
58	            return new PaymentCalculation(BigDecimal.ZERO, orderTotal, installments, installmentAmount);
59	        }
60	
61	        BigDecimal monthlyRate = new BigDecimal("0.0199");
62	        BigDecimal onePlusRate = BigDecimal.ONE.add(monthlyRate);
